text:
{
  "questions": [
    {
      "n": 1,
      "start": "De modifier l’article 2 de la loi sur les préfets et les préfètes (LPr)",
      "end": "afin d’ajouter une condition d’éligibilité exigeant que les candidates et candidats qui se présentent à une élection à la préfecture soient domiciliés dans l’arrondissement administratif dans lequel ils se présentent."
    },
    {
      "n": 2,
      "start": "De modifier l’alinéa 1 de l’article 2 de la loi sur les préfets et les préfètes (LPr)",
      "end": "afin d’exiger que les candidates et candidats qui se présentent jouissent du droit de vote en matière communale, cantonale et fédérale."
    },
    {
      "n": 3,
      "start": "D’étudier la possibilité d’augmenter le nombre de signatures requises pour déposer une candidature",
      "end": "et de modifier l’alinéa 1 de l’article 116 de la loi sur les droits politiques (LDP)."
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Der Regierungsrat wird beauftragt, Artikel 2 RStG dahingehend zu ändern, dass als Wählbarkeitsvoraussetzung verlangt wird, dass die Kandidatinnen und Kandidaten, die sich für die Wahl in das Regierungsstatthalteramt zur Verfügung stellen, ihren Wohnsitz im Verwaltungskreis haben, in dem sie sich zur Wahl stellen.",
      "end": "und dies seit mindestens drei Monaten (Hinzufügen der Stimmberechtigung in kommunalen und kantonalen Angelegenheiten, zusätzlich zur bereits vorgesehenen Stimmberechtigung in eidgenössischen Angelegenheiten)."
    },
    {
      "n": 2,
      "start": "Artikel 2 Absatz 1 RStG dahingehend zu ändern, dass die Kandidatinnen und Kandidaten, die sich zur Wahl stellen, in eidgenössischen, kantonalen und kommunalen Angelegenheiten stimmberechtigt sind.",
      "end": null
    },
    {
      "n": 3,
      "start": "zu prüfen, ob die Anzahl Unterschriften, die für die Einreichung einer Kandidatur erforderlich sind, erhöht werden kann, und entsprechend Artikel 116 Absatz 1 des Gesetzes über die politischen Rechte (PRG) zu ändern.",
      "end": null
    }
  ],
  "submitter": "Heyer (Perrefitte, PLR) (porte-parole)",
  "co_signatories": [
    "Gagnebin (Tramelan, PS)",
    "Ochsenbein (Bévilard, UDC)",
    "Jeanneret (St-Imier, PLR)",
    "Saïd (Biel/Bienne, PS)",
    "Pauli (Nidau, PLR)",
    "Gerber (Reconvilier, PEV)",
    "Bühler (Romont BE, Le Centre)",
    "von Wattenwyl (Tramelan, Les VERT-E-S)",
    "Klopfenstein (Corgémont, UDC)",
    "Tobler (Moutier, UDC)",
    "Hess (Nidau, PLR)"
  ],
  "recommendation": "accept",
  "reasoning": {
    "start": "Der Regierungsrat befürwortet grundsätzlich die Stossrichtung der Motion.",
    "end": "Er beantragt deshalb, die Motion in der Form des Postulates anzunehmen."
  }
}
